class Solution:
    def mostScoops(self, flavours: List[int]) -> int:
        n, best = len(flavours), 0
        for i in range(n):
            taken, j = set(), i
            while j < n and (flavours[j] in taken or len(taken) < 2):
                taken.add(flavours[j])
                j += 1
            best = max(best, j - i)
        return best

