class Solution {
    public int mostScoops(int[] flavours) {
        int n = flavours.length, best = 0;
        for (int i = 0; i < n; i++) {
            int a = flavours[i], b = -1, j = i;
            while (j < n && (flavours[j] == a || flavours[j] == b || b == -1)) {
                if (flavours[j] != a && b == -1) b = flavours[j];
                j++;
            }
            best = Math.max(best, j - i);
        }
        return best;
    }
}

