class Solution:
    def mostScoops(self, flavours: List[int]) -> int:
        count = [0] * len(flavours)
        left = distinct = best = 0
        for i, f in enumerate(flavours):
            count[f] += 1
            if count[f] == 1:
                distinct += 1
            while distinct > 2:
                g = flavours[left]
                count[g] -= 1
                if count[g] == 0:
                    distinct -= 1
                left += 1
            best = max(best, i - left + 1)
        return best

