        int n = flavours.length, left = 0, distinct = 0, best = 0;
        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            if (count[flavours[i]]++ == 0) distinct++;
            while (distinct > 2) if (--count[flavours[left++]] == 0) distinct--;
            best = Math.max(best, i - left + 1);
        }
        return best;
    }
}

