int mostScoops(int* flavours, int flavoursSize) {
    int n = flavoursSize, left = 0, distinct = 0, best = 0;
    int* count = calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) {
        if (count[flavours[i]]++ == 0) distinct++;
        while (distinct > 2) if (--count[flavours[left++]] == 0) distinct--;
        if (i - left + 1 > best) best = i - left + 1;
    }
    free(count);
    return best;
}
